#!/usr/bin/env bash
set -euo pipefail
ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.."&&pwd)";EXP_ROOT="${EXP_ROOT:-/linxi/dataset/FGDD_pixels/aircraft_bbox_native_warp_seed0_v1}";PIXEL_ROOT=/linxi/dataset/FGDD_pixels/aircraft_bbox_seed0_v1;DATA_ROOT=/linxi/dataset/FG_SRe2L_repro/v1/datasets;TEACHER=/linxi/dataset/FG_SRe2L_standard/v1/teachers/A_imsize224/tseed42/ResNet18.pth;R0_FKD=/linxi/dataset/FG_HardAugFactorial_v2/aircraft_ipc3_v1/fkd/fullframe_cutmix/random_real/source_seed0/ipc3_bs20_ipc3;R0_RESULT=/linxi/dataset/FG_SoftAugFactorial_v2/aircraft_ipc3_v1;GPUS=(${GPUS:-0 1});mkdir -p "$EXP_ROOT"/{construction,logs,status,locks,fkd,results,post_eval,summary,audits};ts(){ date --iso-8601=seconds; };IMAGES="$EXP_ROOT/construction/selected/native_subject_warp/ipc3";FKD="$EXP_ROOT/fkd/native_subject_warp/ipc3_bs20_ipc3"
main(){ exec 9>"$EXP_ROOT/locks/launcher.lock";flock -n 9||exit 75;rm -f "$EXP_ROOT/status/launcher.failed" "$EXP_ROOT/status/launcher.complete";echo "$(ts) started new_fkd=1 new_students=3">"$EXP_ROOT/status/launcher.running";if [[ ! -f $EXP_ROOT/construction/construction_manifest.json ]];then python "$ROOT_DIR/CV-DD/fine_grained/prepare_aircraft_bbox_native_warp.py" --source-manifest "$PIXEL_ROOT/construction/construction_manifest.json" --output-root "$EXP_ROOT/construction">"$EXP_ROOT/logs/construction.log" 2>&1;fi;echo "$(ts) complete">"$EXP_ROOT/status/construction.complete";if [[ ! -f $FKD/relabel_manifest.json ]];then CUDA_VISIBLE_DEVICES=0 PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION=python python -u "$ROOT_DIR/CV-DD/fine_grained/rescore_fkd_views.py" --image-root "$IMAGES" --source-fkd "$R0_FKD" --output-fkd "$FKD" --teacher "$TEACHER" --ipc 3 --classes 100 --dataset-name A_imsize224 --epochs 400 --batch-size 20 --workers 8 --seed 42 --fkd-seed 42 --mean .4865 .5177 .5425 --std .2124 .2051 .2375 >"$EXP_ROOT/logs/relabel.log" 2>&1;fi;python "$ROOT_DIR/CV-DD/fine_grained/audit_fkd.py" --fkd-dir "$FKD" --images 300 --classes 100 --batch-size 20 --epochs 400 --output "$FKD/fkd_audit.json">>"$EXP_ROOT/logs/relabel.log" 2>&1;python "$ROOT_DIR/CV-DD/fine_grained/audit_fkd_metadata_alignment.py" --reference "$R0_FKD" --candidate "$FKD" --output "$EXP_ROOT/audits/fkd_vs_r0_metadata.json">>"$EXP_ROOT/logs/relabel.log" 2>&1;echo "$(ts) complete">"$EXP_ROOT/status/relabel.complete";local pids=() i=0 s gpu p failed=0;for s in 42 43 44;do gpu=${GPUS[$((i%2))]};result="$EXP_ROOT/results/native_subject_warp/ipc3_sseed$s.json";log="$EXP_ROOT/logs/eval_s$s.log";mkdir -p "$(dirname "$result")";CUDA_VISIBLE_DEVICES=$gpu PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION=python OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1 python -u "$ROOT_DIR/CV-DD/validate/train_fkd.py" --model ResNet18 --ipc 3 --exp-name "bbox_native_warp_s$s" --original-data-path "$IMAGES" --fkd-path "$FKD" --output-dir "$EXP_ROOT/post_eval/sseed$s" --batch-size 20 --epochs 400 --dataset-name A_imsize224 --gradient-accumulation-steps 2 --mix-type cutmix --workers 8 --persistent-workers --fkd_seed 42 --train-seed "$s" --temperature 20 --student-initialization imagenet-v1 --student-protocol-name standard_protocol_v2_bbox_native_warp --adamw-weight-decay 1e-5 --adamw-beta1 .9 --adamw-beta2 .999 --adamw-eps 1e-8 --adamw-backbone-lr 1e-4 --adamw-head-lr 1e-3 --cosine-t-max 400 --cosine-eta-min 0 --val-dir "$DATA_ROOT/A_imsize224/test" --disable-wandb --per-class-output "$result">"$log" 2>&1&pids+=("$!");i=$((i+1));done;for p in "${pids[@]}";do wait "$p"||failed=1;done;((failed==0));python "$ROOT_DIR/CV-DD/fine_grained/summarize_aircraft_bbox_native_warp.py" --root "$EXP_ROOT" --r0-root "$R0_RESULT" --letterbox-root "$PIXEL_ROOT">"$EXP_ROOT/logs/summary.log" 2>&1;rm -f "$EXP_ROOT/status/launcher.running";echo "$(ts) complete">"$EXP_ROOT/status/launcher.complete";}
trap 'r=$?;if((r));then rm -f "$EXP_ROOT/status/launcher.running";echo "$(ts) exit=$r">"$EXP_ROOT/status/launcher.failed";fi' EXIT
main
